/**
 * Generates CSS from the Hearth design system. Source of truth: design/hearth/tokens.json.
 * Run: pnpm --filter @thoth/ui tokens   (never edit the generated files by hand)
 */
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const root = (p: string) => fileURLToPath(new URL(`../../../${p}`, import.meta.url));
const out = (p: string) => fileURLToPath(new URL(`../src/styles/${p}`, import.meta.url));

type Themed = string | Record<string, string>;
interface Token {
  name: string;
  value: Themed;
  usage?: string;
}
interface TypeStyle {
  name: string;
  fontSize: string;
  lineHeight: string;
  fontWeight: number;
  letterSpacing?: string;
}
const t = JSON.parse(readFileSync(root("design/hearth/tokens.json"), "utf8")) as {
  color: { themes: { id: string }[]; tokens: Token[] };
  type: { families: Record<string, string>; groups: { family: string; styles: TypeStyle[] }[] };
  spacing: { tokens: Token[] };
  radius: { tokens: Token[] };
  shadow: { tokens: Token[] };
};

const HEADER =
  "/* GENERATED by packages/ui/scripts/build-tokens.ts from design/hearth. Do not edit. */\n";
const [light, dark] = t.color.themes.map((x) => x.id) as [string, string];
const themed = [...t.color.tokens, ...t.shadow.tokens];
const val = (v: Themed, th: string) => (typeof v === "string" ? v : (v[th] ?? v[light] ?? ""));
const block = (sel: string, lines: string[]) => `${sel} {\n${lines.join("\n")}\n}\n`;
const vars = (th: string) => themed.map((k) => `  --${k.name}: ${val(k.value, th)};`);

// 1. tokens.css: CSS variables, light default, dark by system preference or [data-theme].
let css = HEADER;
css += block(':root, [data-theme="light"]', vars(light));
css += `@media (prefers-color-scheme: dark) {\n${block(':root:not([data-theme="light"])', vars(dark))}}\n`;
css += block('[data-theme="dark"]', vars(dark));
css += block(":root", [
  ...[...t.spacing.tokens, ...t.radius.tokens].map((k) => `  --${k.name}: ${k.value as string};`),
  ...Object.entries(t.type.families).map(([k, v]) => `  --font-${k}: ${v};`),
]);
writeFileSync(out("tokens.css"), css);

// 2. theme.css: exposes tokens to Tailwind v4 (bg-surface-100, text-ink, rounded-lg, font-serif, type-body...).
let theme = `${HEADER}@theme inline {\n`;
for (const k of t.color.tokens) theme += `  --color-${k.name}: var(--${k.name});\n`;
for (const k of t.radius.tokens)
  theme += `  --radius-${k.name.replace("radius-", "")}: ${k.value as string};\n`;
for (const k of t.shadow.tokens)
  theme += `  --shadow-hearth-${k.name.replace("shadow-", "")}: var(--${k.name});\n`;
for (const [f, v] of Object.entries(t.type.families)) theme += `  --font-${f}: ${v};\n`;
theme += "  --spacing: 4px;\n}\n";
for (const g of t.type.groups) {
  for (const s of g.styles) {
    theme += `@utility type-${s.name} {\n  font-family: var(--font-${g.family});\n  font-size: ${s.fontSize};\n  line-height: ${s.lineHeight};\n  font-weight: ${s.fontWeight};\n  letter-spacing: ${s.letterSpacing ?? "0"};\n${s.name === "overline" ? "  text-transform: uppercase;\n" : ""}}\n`;
  }
}
writeFileSync(out("theme.css"), theme);

// 3. components.css: Hearth's component classes, minus the demo-only body rule.
const bundle = readFileSync(root("design/hearth/components/bundle.css"), "utf8").replace(
  /body\s*\{[^}]*\}\s*/,
  "",
);
writeFileSync(out("components.css"), HEADER + bundle);
console.log("Wrote tokens.css, theme.css, components.css");
